"""Algorithm 1 -- Quarter-Disc Enumeration of the Berggren Box."""

from __future__ import annotations

from math import gcd, isqrt
from typing import Iterator, List, Tuple

Triple = Tuple[int, int, int]
Pair = Tuple[int, int]


def euclid_triple(m: int, n: int) -> Triple:
    """Euclid's map E(m,n) = (m^2 - n^2, 2mn, m^2 + n^2)."""
    return (m * m - n * n, 2 * m * n, m * m + n * n)


def admissible_pairs_in_disc(h: int) -> Iterator[Pair]:
    """Yield every (m,n) with 0 < n < m, gcd(m,n)=1, m+n odd and m^2+n^2 <= H.

    These are precisely the Euclid parameters of the Berggren-generated triples
    lying in the cube [1,H]^3: the leg conditions a <= H and b <= H are implied by
    the hypotenuse condition, because m^2-n^2 < m^2+n^2 and 2mn < m^2+n^2.
    """
    for m in range(2, isqrt(h) + 1):
        for n in range(1, m):
            if (m + n) % 2 == 1 and gcd(m, n) == 1 and m * m + n * n <= h:
                yield (m, n)


def berggren_box(h: int) -> List[Triple]:
    """All triples of [1,H]^3 generated from the seed (3,4,5), in O(H log H) time."""
    return [euclid_triple(m, n) for (m, n) in admissible_pairs_in_disc(h)]


def primitive_box(h: int) -> List[Triple]:
    """All primitive Pythagorean triples of [1,H]^3 (both seeds, no repetitions)."""
    out: List[Triple] = []
    for (a, b, c) in berggren_box(h):
        out.append((a, b, c))
        out.append((b, a, c))
    return out


if __name__ == "__main__":
    for h in (100, 1000, 10000, 100000):
        nodes = berggren_box(h)
        assert all(max(t) <= h and t[0] ** 2 + t[1] ** 2 == t[2] ** 2 for t in nodes)
        assert len(set(nodes)) == len(nodes)
        print(f"H = {h:>7}:  {len(nodes):>6} Berggren triples, "
              f"{2 * len(nodes):>6} primitive triples, ratio to H = {len(nodes) / h:.6f}")

"""Algorithm 2 -- Address Decoding by the Descent Trichotomy."""

from __future__ import annotations

from math import gcd, isqrt
from typing import List, Tuple

Triple = Tuple[int, int, int]
Pair = Tuple[int, int]

MATRICES = {
    "A": ((1, -2, 2), (2, -1, 2), (2, -2, 3)),
    "B": ((1, 2, 2), (2, 1, 2), (2, 2, 3)),
    "C": ((-1, 2, 2), (-2, 1, 2), (-2, 2, 3)),
}
ROOT: Triple = (3, 4, 5)


def apply_word(word: str, v: Triple = ROOT) -> Triple:
    """Apply the letters of `word` to `v` in order."""
    for letter in word:
        m = MATRICES[letter]
        v = tuple(sum(m[i][j] * v[j] for j in range(3)) for i in range(3))  # type: ignore[assignment]
    return v


def euclid_params(v: Triple) -> Pair:
    """Recover (m,n) from a node: m = sqrt((a+c)/2), n = sqrt((c-a)/2)."""
    a, _b, c = v
    return (isqrt((a + c) // 2), isqrt((c - a) // 2))


def is_odd_leg_ppt(v: Triple) -> bool:
    a, b, c = v
    return a > 0 and b > 0 and c > 0 and a * a + b * b == c * c and gcd(a, b) == 1 and a % 2 == 1


def decode_address(v: Triple) -> str:
    """The unique word W in {A,B,C}* with W(3,4,5) = v.

    Each iteration reads off the last letter from the position of m relative to 2n
    and 3n -- the three image cones n<m<2n, 2n<m<3n, 3n<m are disjoint -- and then
    undoes that generator.  The step is a subtractive Euclidean step on (m,n), so it
    terminates; uniqueness of the output is freeness of the generated monoid.
    """
    if not is_odd_leg_ppt(v):
        raise ValueError(f"{v} is not a node of the tree grown from (3,4,5)")
    m, n = euclid_params(v)
    letters: List[str] = []
    while m > 2:
        if m < 2 * n:
            letters.append("A")
            m, n = n, 2 * n - m
        elif m < 3 * n:
            letters.append("B")
            m, n = n, m - 2 * n
        else:
            letters.append("C")
            m, n = m - 2 * n, n
    return "".join(reversed(letters))


if __name__ == "__main__":
    import itertools

    for length in range(0, 6):
        for word in map("".join, itertools.product("ABC", repeat=length)):
            assert decode_address(apply_word(word)) == word
    print("round trip verified for all 3^0 + ... + 3^5 = 364 addresses")
    for v in [(3, 4, 5), (5, 12, 13), (21, 20, 29), (15, 8, 17), (275, 252, 373),
              (697, 696, 985)]:
        print(f"{str(v):>18}  ->  address '{decode_address(v) or 'the root'}'")

"""Algorithm 3 -- Exact Uniform Sampling of Primitive Pythagorean Triples."""

from __future__ import annotations

import random
from math import gcd, isqrt
from typing import Dict, List, Tuple

Triple = Tuple[int, int, int]
Pair = Tuple[int, int]


def admissible_pairs_in_disc(h: int) -> List[Pair]:
    return [
        (m, n)
        for m in range(2, isqrt(h) + 1)
        for n in range(1, m)
        if (m + n) % 2 == 1 and gcd(m, n) == 1 and m * m + n * n <= h
    ]


def euclid_triple(m: int, n: int) -> Triple:
    return (m * m - n * n, 2 * m * n, m * m + n * n)


class TripleSampler:
    """Exactly uniform sampler on the primitive Pythagorean triples of [1,H]^3.

    Construction costs O(H log H) time and Theta(H) memory; each draw is O(1).
    Correctness rests on three facts: Euclid's map is a bijection from the visible
    opposite-parity lattice points of the quarter disc of radius sqrt(H) onto the
    triples with odd first leg; the leg swap is a bijection onto the triples with
    even first leg; and the two families are disjoint and exhaust the target.

    Setting `both_seeds=False` reproduces the natural bug: sampling from the single
    seed (3,4,5) covers exactly half the target set, forever.
    """

    def __init__(self, h: int, both_seeds: bool = True, seed: int | None = None) -> None:
        self.h = h
        self.both_seeds = both_seeds
        self.pairs = admissible_pairs_in_disc(h)
        self.rng = random.Random(seed)

    def support_size(self) -> int:
        return (2 if self.both_seeds else 1) * len(self.pairs)

    def target_size(self) -> int:
        """The number of primitive Pythagorean triples in the cube."""
        return 2 * len(self.pairs)

    def coverage(self) -> float:
        return self.support_size() / self.target_size()

    def draw(self) -> Triple:
        k = len(self.pairs)
        j = self.rng.randrange(self.support_size())
        m, n = self.pairs[j % k]
        a, b, c = euclid_triple(m, n)
        return (a, b, c) if (j < k or not self.both_seeds) else (b, a, c)


if __name__ == "__main__":
    h = 2000
    for both in (True, False):
        s = TripleSampler(h, both_seeds=both, seed=7)
        seen: Dict[Triple, int] = {}
        for _ in range(200_000):
            t = s.draw()
            seen[t] = seen.get(t, 0) + 1
        print(f"both_seeds={both!s:>5}: support {s.support_size():>5} of target "
              f"{s.target_size():>5}  (coverage {s.coverage():.3f}); "
              f"distinct triples drawn: {len(seen)}")
    print("with one seed every sample has odd first leg -- exactly half the target "
          "is unreachable, at every H.")
